INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_234', 'mbe', '234', '139', 'MBE-1978-83-part1', '', '85', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'Assume for this question only that the programs completed on July 5 had cut processing time by one-half for all of HDS''s financial transactions. Is HDS entitled to renounce the contract because of Cl"s delay in completion?', 'Yes, because "CP to complete by July 1" is an express condition,', 'Yes, because the doctrine of substantial performance does not apply to commercial contracts.', 'No, because both parties manifested an understanding that time was not of the essence.', 'No, because the contract did not contain a liquidated damages clause dealing with delay in completion.', 'C', 'Ordinarily, in contracts where time is not of the essence, a failure to complete the work within the specified time will not terminate the contract, but it will subject the contractor to damages for the delay. See 13 Am.Jur.2d Building and Construction Contracts s 47.', 'mbe_2340', 0, '85'),
('mbe_235', 'mbe', '235', '139', 'MBE-1978-83-part1', '', '86', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'Assume for this question only that CP''s delay in completion did not give HDS the right to renounce the contract and that the parties'' escrow agreement was enforceable. Is CP entitled to recover damages for breach of the contract?', 'Yes, because CP had substantially performed.', 'Yes, because the programs would save HDS $12,000 a year.', 'No, because shortening the processing time by one-half was an express condition subsequent.', 'No, because HDS''s computer systems manager did not certify satisfactory completion of the programs.', 'D', 'A condition, which follows liability on a contract but provides for a contingency which, if it occurs, will defeat a contract already in effect, is a condition subsequent. See Nichols Bros. Investments v. Rector–Phillips–Morse, Inc. and Bill Haupt, 33 Ark.App. 47, 801 S.W.2d 308 (1990) (citing 17 Am.Jur.2d Contracts § 323 (1964)).', 'mbe_2341', 0, '86'),
('mbe_236', 'mbe', '236', '139', 'MBE-1978-83-part1', '', '87', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'Assume for this question only that CP was in breach of contract because of its four-day delay in completion and that an express condition precedent to HDS''s duty to pay the contract price has failed. Can CP nevertheless recover the reasonable value of its services?', 'Yes, because continued use of the programs by HDS would save at least $12,000 a year.', 'Yes, because HDS was continuing to use programs created by CP for which, as HDS knew, CP expected to be paid.', 'No, because failure of an express condition precedent excused HDS from any duty to compensate CP.', 'No, because such a recovery by CP would be inconsistent with a claim by HOS against CP for breach of contract.', 'B', 'failure to satisfy a condition precedent ordinarily is considered an affirmative defense.', 'mbe_2342', 0, '87'),
('mbe_278', 'mbe', '278', '166', 'MBE-1978-83-part1', '', '130', 'Miller is tried for armed robbery of the First Bank of City.', 'The prosecution, in its case in chief, offers evidence that when Miller was arrested one day after the crime, he had a quantity of heroin and a hypodermic needle in his possession. This evidence should be', 'admitted to prove Miller''s motive to commit the crime', 'admitted to prove Miller''s propensity to commit crimes', 'excluded, because its probative value is substantially outweighed by the danger of unfair prejudice', 'excluded, because such evidence may be offered only to rebut evidence of good character offered by defendant', 'C', '“In determining whether the prejudicial effect of otherwise relevant evidence outweighs its probative value, we consider whether: (1) ... the facts offered may unduly arouse the jury''s emotions, hostility or sympathy, (2) ... the proof and answering evidence it provokes may create a side issue that will unduly distract the jury from the main issues, (3) ... the evidence offered and the counterproof will consume an undue amount of time, and (4) ... the defendant, having no reasonable ground to anticipate the evidence, is unfairly surprised and unprepared to meet it.” (Internal quotation marks omitted.) Id., at 586–87, 10 A.3d 1005.', 'mbe_2343', 0, '130'),
('mbe_279', 'mbe', '279', '166', 'MBE-1978-83-part1', '', '131', 'Miller is tried for armed robbery of the First Bank of City.', 'The prosecutor offers the testimony of a bartender that when he saw the money in Miller''s wallet, he said, "You must have robbed a bank," to which Miller made no reply. This evidence is', 'admissible to prove that Miller''s conduct caused the bartender to believe that Miller robbed the bank', 'admissible as a statement made in the presence of the defendant', 'inadmissible, because it would violate Miller''s privilege against self-incrimination', 'inadmissible, because Miller had no reason to respond to the bartender''s statement', 'D', '“Although relevant, evidence may be excluded by the trial court if the court determines that the prejudicial effect of the evidence outweighs its probative value.... Of course, [a]ll adverse evidence is damaging to one''s case, but it is inadmissible only if it creates undue prejudice so that it threatens an injustice were it to be admitted.... The test for determining whether evidence is unduly prejudicial is not whether it is damaging to the defendant but whether it will improperly arouse the emotions of the jury.... Reversal is required only whe[n] an abuse of discretion is manifest or whe[n] injustice appears to have been done.” (Citations omitted; emphasis added; internal quotation marks omitted.) State v. Wilson, 308 Conn. 412, 429–30, 64 A.3d 91 (2013).', 'mbe_2344', 0, '131'),
('mbe_280', 'mbe', '280', '166', 'MBE-1978-83-part1', '', '132', 'Miller is tried for armed robbery of the First Bank of City.', 'At the request of police, the teller who was robbed prepared a sketch bearing a strong likeness to Miller, but the teller died in an automobile accident before Miller was arrested. At trial the prosecution offers the sketch. The sketch is', 'admissible as an identification of a person after perceiving him', 'admissible as past recollection recorded', 'inadmissible as hearsay not within any exception', 'inadmissible as an opinion of the teller', 'C', 'Past recollection recorded “allows a witness with a faded memory to testify from notes or a memorandum that the witness can show was made by her or under her direction while the information was fresh in the witness''[s] memory and reflects that knowledge correctly.” The rule “requires the offering party to prove and the trial judge to find that the witness ‘has insufficient recollection to enable the witness to testify fully and accurately’ (taking into account the extent to which the memory can be refreshed from examination of the writing).” Under KRE 803(5), “the recorded recollection is admissible, but only after verification of its accuracy. Even if admitted, ‘the memorandum or record may be read into evidence but may not be received as an exhibit unless offered by an adverse party.’ ” If a party''s notes do refresh the party''s recollection, “there is no need to admit the recording into evidence, because the witness will be able to testify from his or her refreshed memory.”', 'mbe_2345', 0, '132'),
('mbe_281', 'mbe', '281', '166', 'MBE-1978-83-part1', '', '133', 'Miller is tried for armed robbery of the First Bank of City.', 'Miller testified on direct examination that he had never been in the First Bank of City. His counsel asks, "What, if anything, did you tell the police when you were arrested?" If his answer would be, "I told them I had never been in the bank," this answer would be', 'admissible to prove Miller had never been in the bank', 'admissible as a prior consistent statement', 'inadmissible as hearsay not within any exception', 'inadmissible, because it was a self-serving statement by a person with a substantial motive to fabricate', 'C', 'However, prior consistent statements are admissible as non-hearsay if: (1) the individual who made the prior consistent statement testifies at trial and is subject to cross-examination concerning the statement; and (2) the statement is offered in an effort to rebut an express or implied accusation of improper influence, motive or recent fabrication. See Chandler, 702 So.2d at 197–98; see also § 90.801(2)(b), Fla. Stat. (2001). Both conditions must be met for admission of a prior consistent statement as nonhearsay. Harris v. State, 843 So.2d 856, 862 (Fla.2003).', 'mbe_2346', 0, '133'),
('mbe_282', 'mbe', '282', '166', 'MBE-1978-83-part1', '', '134', 'Miller is tried for armed robbery of the First Bank of City.', 'On cross-examination of Miller, the prosecutor asks Miller whether he was convicted the previous year of tax fraud. This question is', 'proper to show that Miller is inclined to lie', 'proper to show that Miller is inclined to steal money', 'improper, because the conviction has insufficient similarity to the crime charged', 'improper, because the probative value of the evidence is outweighed by the danger of unfair prejudice', 'A', 'A trial court has discretion to permit leading questions on direct examination when a witness is reluctant, hostile, or overly nervous.', 'mbe_2347', 0, '134'),
('mbe_284', 'mbe', '284', '168', 'MBE-1978-83-part1', '', '136', '', 'Tess occupied an apartment in a building owned by Len. She paid rent of $125 in advance each month. During the second month of occupancy, Tess organized the tenants in the building as a tenants'' association and the association made demands of Len concerning certain repairs and improvements the tenants wanted. When Tess tendered rent for the third month, Len notified her that rent for the fourth and subsequent months would be $200 per month. Tess protested and pointed out that all other tenants paid rent of $125 per month. Thereupon, Len gave the required statutory notice that the tenancy was being terminated at the end of the third month. By an appropriate proceeding, Tess contests Len''s right to terminate. If Tess succeeds, it will be because', 'a periodic tenancy was created by implication', 'the doctrine prohibiting retaliatory eviction is part of the law of the jurisdiction', 'the $200 rent demanded violates the agreement implied by the rate charged to other tenants', 'the law implies a term of one year in the absence of any express agreement', 'B', '"Retaliatory evidence" is called the doctrine of "curative admissibility" in the cases. It is a doctrine which seeks to level the playing field in a way. Under it, when one party "opens the door" by introducing otherwise inadmissible evidence, the opposing party is provided with the unconditional right to rebut such evidence with other illegal evidence on the same subject.
The law is that "even though a party introduces evidence that may be immaterial or illegal, his opponent has the right to rebut such evidence and this right is unconditional." A party "who has brought out evidence on a certain subject has no valid complaint as to the trial court''s action in allowing his opponent or adversary to introduce evidence on the same subject."', 'mbe_2348', 0, '136'),
('mbe_313', 'mbe', '313', '181', 'MBE-1978-83-part1', '', '165', '', 'Lester, the owner in fee simple of a small farm consisting of thirty acres of land improved with a house and several outbuildings, leased the same to Tanner for a ten-year period. After two years had expired, the government condemned twenty acres of the property and allocated the compensation award to Lester and Tanner according to their respective interest so taken. It so happened, how. ever, that the twenty acres taken embraced all of the farm''s tillable land, leaving only the house, outbuildings, and a small woodlot. There is no applicable statute in the jurisdiction where the property is located nor any provision in the lease relating to condemnation. Tanner quit possession, and Lester brought suit against him to recover rent, Lester will', 'lose, because there has been a frustration of purpose which excuses Tanner from further performance of his contract to pay rent', 'lose, because there has been a breach of the implied covenant of quiet enjoyment by Lester ''s inability to provide Tanner with possession of the whole of the property for the entire term', 'win, because of the implied warranty on the part of the tenant to return the demised premises in the same condition at the end of the term as they were at the beginning', 'win, because the relationship of landlord and tenant was unaffected by the condemnation, thus leaving Tanner still obligated to pay rent', 'D', '“[a] covenant for quiet enjoyment of the premises is necessarily implied in every lease and goes to the extent of [representing] that the landlord has a good title and can give a free and unencumbered lease of the premises for the term stipulated.”', 'mbe_2349', 0, '165'),
('mbe_377', 'mbe', '377', '214', 'MBE-1978-83-part5', '', '29', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wants to introduce testimony from Sheriff concerning a discussion between Sheriff and Passerby at the police station after the accident, when Passerby excitedly exclaimed, "Pedersen ran out in the street and was not in the crosswalk!" Sheriff duly recorded the statement in an official police report. The trial judge should rule Sheriff''s oral testimony', 'admissible as a spontaneous utterance', 'admissible as based on past recollection recorded', 'inadmissible because Passerby has not been shown unavailable as a witness', 'inadmissible under the excited utterance exception because it can be a product of reflection and deliberation', 'D', '[I]n order for an excited utterance to be admissible, the following requirements must be met: (1) there must have been an event startling enough to cause nervous excitement; (2) the statement must have been made before there was time to contrive or misrepresent; and (3) the statement must have been made while the person was under the stress of excitement caused by the startling event.
Stoll v. State, 762 So.2d 870, 873 (Fla. 2000).', 'mbe_2350', 0, '29'),
('mbe_378', 'mbe', '378', '214', 'MBE-1978-83-part5', '', '30', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wants to introduce testimony of Sheriff that at the police station Carr told Sheriff, "I think this was probably my fault." The trial judge should rule this testimony', 'admissible as a part of the res gestae', 'admissible as an admission of a party', 'inadmissible because it includes a conclusion of law which the declarant was not qualified to make', 'inadmissible because it constitutes an opinion rather than an admission of specific facts', 'B', 'For an admission by a party-opponent to be admissible: 1) the statement must be a conscious or voluntary acknowledgment by a party-opponent of the existence of certain facts; 2) the matter acknowledged must be relevant to the cause of the party offering the admission; and 3) the matter acknowledged must be unfavorable to or inconsistent with the position now taken by the party-opponent. Bowls v. Scarborough, 950 S.W.2d 691, 702 (Mo.App.W.D.1997).', 'mbe_2351', 0, '30'),
('mbe_379', 'mbe', '379', '214', 'MBE-1978-83-part5', '', '31', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wishes to prove that after the accident Carr went to Pedersen and offered $1,000 to settle Pedersen''s claim. The trial judge should rule this evidence', 'admissible as an admission of a party', 'admissible as an admission to show Carr''s liability, provided the court gives a cautionary instruction that the statement should not be considered as bearing on the issue of damages', 'inadmissible since it is not relevant either to the question of liability or the question of damages', 'inadmissible because even though relevant and an admission, the policy of the law is to encourage settlement negotiations', 'D', '(a) Prohibited Uses. Evidence of the following is not admissible — on behalf of any party — either to prove or disprove the validity or amount of a disputed claim or to impeach by a prior inconsistent statement or a contradiction: (1) furnishing, promising, or offering — or accepting, promising to accept, or offering to accept — a valuable consideration in compromising or attempting to compromise the claim; and (2) conduct or a statement made during compromise negotiations about the claim — except when offered in a criminal case and when the negotiations related to a claim by a public office in the exercise of its regulatory, investigative, or enforcement authority. b) Exceptions. The court may admit this evidence for another purpose, such as proving a witness’s bias or prejudice, negating a contention of undue delay, or proving an effort to obstruct a criminal investigation or prosecution.', 'mbe_2352', 0, '31'),
('mbe_380', 'mbe', '380', '214', 'MBE-1978-83-part5', '', '32', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wants to have Sheriff testify to the following statement made to him by Walter Passenger, out of the presence of Carr: "We were returning from a party at which we had all been drinking." The trial judge should rule this testimony', 'admissible as an admission of a party', 'admissible as a declaration against interest', 'inadmissible as hearsay not within any exception', 'inadmissible because it would lead the court into nonessential side issues', 'C', 'Hearsay is generally defined as an out-of-court statement made by a declarant and offered for the truth of the matter asserted (see Nucci v. Proper, 95 N.Y.2d 597, 602, 721 N.Y.S.2d 593, 744 N.E.2d 128 [2001]; People v. Buie, 86 N.Y.2d 501, 505, 634 N.Y.S.2d 415, 658 N.E.2d 192 [1995];', 'mbe_2353', 0, '32'),
('mbe_381', 'mbe', '381', '214', 'MBE-1978-83-part5', '', '33', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'On the evening of the day of the accident, Walter Passenger wrote a letter to his sister in which he described the accident. When Walter says he cannot remember some details of the accident, Pedersen''s counsel seeks to show him the letter to assist him in his testimony on direct examination. The trial judge should rule this', 'permissible under the doctrine of present recollection refreshed', 'permissible under the doctrine of past recollection recorded', 'objectionable because the letter was not a spontaneous utterance', 'objectionable because the letter is a self-serving declaration in so far as the witness, Walter, is concerned', 'A', 'In contrast, [u]nder present recollection refreshed the witness'' memory is refreshed or jogged through the employment of a writing, diagram, smell or even touch, and he testifies from his memory so refreshed. Because of the independent origin of the testimony actually elicited, the stimulation of an actual present recollection is not strictly bounded by fixed rules but, rather, is approached on a case-by-case basis looking to the peculiar facts and circumstances present.
Gibson, 333 N.C. at 50, 424 S.E.2d at 107. Because “the evidence is the testimony of the witness at trial, whereas with a past recollection recorded the evidence is the writing itself,” “the foundational questions raised by past recollection recorded are never reached.” Id. The relevant test, then, “is whether the witness has an independent recollection of the event and is merely using the memorandum to refresh details or whether the witness is using the memorandum as a testimonial crutch for something beyond his recall.” State v. York, 347 N.C. 79, 89, 489 S.E.2d 380, 386 (1997).', 'mbe_2354', 0, '33'),
('mbe_385', 'mbe', '385', '217', 'MBE-1978-83-part5', '', '37', '', 'Chase, as seller, and Scott, as buyer, enter into a written contract for the sale and purchase of land which is complete in all respects except that no reference is made to the quality of title to be conveyed. Which of the following will result?', 'The contract will be unenforceable.', 'Chase will be required to convey a marketable title.', 'Chase will be required to convey only what he owned on the date of the contract.', 'Chase will be required to convey only what he owned on the date of the contract plus whatever additional title rights he may acquire prior to the closing date.', 'B', '“Marketable title is one that may be ‘freely made the subject of resale’ and that can be sold at a ‘fair price to a reasonable purchaser or mortgaged to a person of reasonable prudence as security for the loan of money.’ ” Kelley v. Leucadia Fin. Corp., 846 P.2d 1238, 1243 (Utah 1992) (quoting 77 Am.Jur.2d Vendor and Purchaser § 131, at 313–14 (1975)).', 'mbe_2355', 0, '37'),
('mbe_404', 'mbe', '404', '228', 'MBE-1978-83-part6', '', '4', 'Ogden was the fee simple owner of three adjoining vacant lots fronting on a common street in a primarily residential section of a city which had no zoning laws. The lots were identified as Lots 1, 2, and 3. Ogden conveyed Lot 1 to Akers and Lot 2 to Bell. Ogden retained Lot 3, which consisted of three acres of woodland. Bell, whose lot was between the other two, built a house on his lot. Bell''s house included a large window on the side facing Lot 3. The window provided a beautiful view from Bell''s living room, thereby adding value to Bell''s house. Akers erected a house on his lot. Ogden made no complaint to either Akers or Bell concerning the houses they built. After both Akers and Bell had completed their houses, the two of them agreed to and did build a common driveway running from the street to the rear of their respective lots. The driveway was built on the line between the two houses so that one-half of the way was located on each lot. Akers and Bell exchanged right-ofway deeds by which each of them conveyed to the other, his heirs and assigns, an easement to continue the right of way. Both deeds were properly recorded. After Akers and Bell had lived in their respective houses for thirty years, a new public street was built bordering on the rear of Lots 1, 2, and 3. Akers informed Bell that, since the new street removed the need for their common driveway, he considered the right-of-way terminated; therefore, he intended to discontinue its use and expected Bell to do the same. At about the same time, Ogden began the erection of a six-story apartment house on Lot 3. If the apartment house is completed, it will block the view from Bell''s window and will substantially reduce the value of Bell''s lot.', 'In an action brought by Bell to enjoin Akers from interfering with Bell''s continued use of the common driveway between the two lots, the decision should be for', 'Akers, because the termination of the necessity for the easement terminated the easement', 'Akers, because the continuation of the easement after the change of circumstances would adversely affect the marketability of both lots without adding any commensurate value to either', 'Bell, because an incorporeal hereditament lies in grant and cannot be terminated without a writing', 'Bell, because the removal of the need for the easement created by express grant does not affect the right to the easement', 'D', 'An incorporeal hereditament is “[a]n intangible right in land, such as an easement.”  In other contexts, Utah courts have recognized an incorporeal hereditament as an interest in real property. In addressing a case involving a license to prospect and mine ore, the Utah Supreme Court discussed the potential for a mining license to ripen into an incorporeal hereditament and stated: This is not to say that a license is an incorporeal hereditament; it means that the grant was a license as long as it remained executory because it was not in proper form for a conveyance of an incorporeal hereditament. It ripened into an incorporeal hereditament when the licensee entered into enjoyment thereof and made expenditures and improvements. Other jurisdictions hold that revocation will not be allowed in such a case unless the licensee be compensated for his improvements.
This language supports a conclusion that the holder of an incorporeal hereditament would be considered the holder of a form of property interest entitling it to compensation under Utah law.', 'mbe_2356', 0, '4'),
('mbe_405', 'mbe', '405', '228', 'MBE-1978-83-part6', '', '5', 'Ogden was the fee simple owner of three adjoining vacant lots fronting on a common street in a primarily residential section of a city which had no zoning laws. The lots were identified as Lots 1, 2, and 3. Ogden conveyed Lot 1 to Akers and Lot 2 to Bell. Ogden retained Lot 3, which consisted of three acres of woodland. Bell, whose lot was between the other two, built a house on his lot. Bell''s house included a large window on the side facing Lot 3. The window provided a beautiful view from Bell''s living room, thereby adding value to Bell''s house. Akers erected a house on his lot. Ogden made no complaint to either Akers or Bell concerning the houses they built. After both Akers and Bell had completed their houses, the two of them agreed to and did build a common driveway running from the street to the rear of their respective lots. The driveway was built on the line between the two houses so that one-half of the way was located on each lot. Akers and Bell exchanged right-ofway deeds by which each of them conveyed to the other, his heirs and assigns, an easement to continue the right of way. Both deeds were properly recorded. After Akers and Bell had lived in their respective houses for thirty years, a new public street was built bordering on the rear of Lots 1, 2, and 3. Akers informed Bell that, since the new street removed the need for their common driveway, he considered the right-of-way terminated; therefore, he intended to discontinue its use and expected Bell to do the same. At about the same time, Ogden began the erection of a six-story apartment house on Lot 3. If the apartment house is completed, it will block the view from Bell''s window and will substantially reduce the value of Bell''s lot.', 'In an action brought by Bell to enjoin Ogden from erecting the apartment building in such a way as to obstruct the view from Bell''s livingroom window, the decision should be for', 'Bell, because Ogden''s proposed building would be an obstruction of Bell''s natural right to an easement for light and air', 'Bell, because Bell was misled by Ogden''s failure to complain when Bell was building his house', 'Ogden if, but only if, it can be shown that Ogden''s intention to erect such a building was made known to Bell at or prior to the time of Ogden''s conveyance to Bell', 'Ogden, because Bell has no easement for light, air, or view', 'D', 'An easement for light and air will not be implied under any circumstances short of a necessity so absolute as to destroy the use of the plaintiff''s building.', 'mbe_2357', 0, '5'),
('mbe_406', 'mbe', '406', '229', 'MBE-1978-83-part6', '', '6', '', 'Dever was indicted for the murder of Vickers by poison. At trial, the prosecutor calls the county coroner, Dr. Wolfe, who is a board-certified pathologist, to testify that, in accord with good practice in her specialty, she has studied microphotographic slides, made under her supervision by medical assistants, of tissue taken from Vickers'' corpse and that it is Wolfe''s opinion, based on that study, that Vickers died of poisoning. The slides have not been offered in evidence. Dr. Wolfe''s opinion should be', 'excluded, because the cause ofdeathis a critical issue to be decided by the trier of fact', 'excluded, because her opinion is based on facts not in evidence', 'admitted, because Wolfe followed accepted medical practice in arriving at her opinion', 'admitted, because her opinion is based on matters observed pursuant to a duty imposed by law', 'C', 'An expert opinion is competent if it is held to a reasonable degree of scientific or medical certainty. State v. Jackson, 92 Ohio St.3d 436, 751 N.E.2d 946 (2001) citing State v. Benner, 40 Ohio St.3d 301, 313, 533 N.E.2d 701, 714 (1988). The phrase “reasonable certainty” is synonymous with the term “probability.” Id.', 'mbe_2358', 0, '6'),
('mbe_407', 'mbe', '407', '230', 'MBE-1978-83-part6', '', '7', '', 'At the trial of Davis for a murder that occurred in Newtown, the prosecution called Waite, who testified that she saw Davis kill the victim. Davis believed that Waite was 600 miles away in Old Town, engaged in the illegal sale of narcotics, on the day in question. On cross-examination by Davis, Waite was asked whether she had in fact sold narcotics in Old Town on that date. Waite refused to answer on the ground of self-incrimination. The judge, over the prosecutor''s objection, ordered that if Waite did not testify, her direct testimony should be stricken. The order to testify or have the testimony stricken can best be supported on the basis that', 'Waite had not been charged with any crime and, thus, could claim no privilege against self-incrimination', 'Waite''s proper invocation of the privilege prevented adequate cross-examination', 'the public interest in allowing an accused to defend himself or herself outweighs the interest of a non-party witness in the privilege', 'the trial record, independent of testimony, does not establish that Waite''s answer could incriminate her', 'B', 'When a witness refuses to answer cross-examination questions necessary to test the witness''s direct testimony, that refusal undermines the trier of fact''s ability to rely on the witness''s direct testimony, and the trial court may strike the witness''s testimony.', 'mbe_2359', 0, '7'),
('mbe_409', 'mbe', '409', '232', 'MBE-1978-83-part6', '', '9', '', 'On January 15, Carpenter agreed to repair Householder''s house according to certain specifications and to have the work completed by April 1. On March 1, Householder''s property was inundated by flood waters which did not abate until March 15. Householder could not get the house in a condition which would permit Carpenter to begin the repairs until March 31. On that date Carpenter notified Householder that he would not repair the house. Which one of the following facts, if it was the only one true and known to both parties on January 15, would best serve Carpenter as the basis for a defense in an action brought against him by Householder for breach of contract?', 'Carpenter''s busy schedule permitted him to work on Householder''s house only during the month of March.', 'Any delay in making the repairs would not seriously affect Householder''s use of the property.', 'The cost of making repairs was increasing at the rate of 3% a month.', 'The area around Householder''s property was frequently flooded during the month of March.', 'A', 'Under the defense of impossibility of performance, a party''s breach of its contractual obligation will be excused when “changed circumstances have rendered the promise vitally different from what reasonably should have been within the contemplation of both parties when they entered into the contract.” Colo. Performance Corp. v. Mariposa Assocs., 754 P.2d 401, 407 (Colo.Ct.App.1987) (quotation omitted)', 'mbe_2360', 0, '9'),
('mbe_414', 'mbe', '414', '236', 'MBE-1978-83-part6', '', '14', '', 'Pitt sued Dow for damages for injuries that Pitt incurred when a badly rotted limb fell from a curbside tree in front of Dow''s home and hit Pitt. Dow claimed that the tree was on city property and thus was the responsibility of the city. At trial, Pitt offered testimony that a week after the accident, Dow had cut the tree down with a chainsaw. The offered evidence is', 'inadmissible, because there is a policy to encourage safety precautions', 'inadmissible, because it is irrelevant to the condition of the tree at the time of the accident', 'admissible to show the tree was on Dow''s property', 'admissible to show the tree was in a rotted condition', 'C', 'Basically, if evidence is to be admitted at court, it must be relevant, material, and competent. To be considered relevant, it must have some reasonable tendency to help prove or disprove some fact. It need not make the fact certain, but at least it must tend to increase or decrease the likelihood of some fact. Once admitted as relevant evidence, the finder of fact (judge or jury) will determine the appropriate weight to give a particular piece of evidence. A given piece of evidence is considered material if it is offered to prove a fact that is in dispute in a case. Evidence is considered "competent" if it complies with certain traditional notions of reliability. Courts are gradually diminishing the competency rules of evidence by making them issues related to the weight of evidence.', 'mbe_2361', 0, '14'),
('mbe_430', 'mbe', '430', '252', 'MBE-1978-83-part6', '', '30', '', 'A group of children, ranging in age from 8 to 15, regularly played football on the common area of an apartment complex owned by O''Neill. Most of the children lived in the apartment complex, but some lived elsewhere. O''Neill knew that the children played on the common area and had not objected. Peter, a 13-year-old who did not live in the apartment complex, fell over a sprinkler head while running for a pass and broke his leg. Although Peter had played football on the common area before, he had never noticed the sprinkler heads, which protruded one inch above the ground and were part of a permanently installed underground sprinkler system. If a claim is asserted on Peter''s behalf, Peter will', 'prevail if the sprinkler head was a hazard that Peter probably would not discover', 'prevail, because O''Neill had not objected to children playing on the common area', 'not prevail, because Peter did not live in the apartment complex', 'not prevail unless the sprinkler heads were abnormally dangerous to users of the common area', 'A', 'a landowner has a duty to maintain his or her property in a reasonably safe condition, which includes providing a safe means of ingress and egress to tenants (see Peralta v. Henriquez, 100 N.Y.2d 139, 144, 760 N.Y.S.2d 741, 790 N.E.2d 1170 [2003]; Basso v. Miller, 40 N.Y.2d 233, 241, 386 N.Y.S.2d 564, 352 N.E.2d 868 [1976]; Gallagher v. St. Raymond''s R.C. Church, 21 N.Y.2d 554, 557, 289 N.Y.S.2d 401, 236 N.E.2d 632 [1968] ). The scope of such duty is determined “ ‘in view of all the circumstances, including the likelihood of injury to others, the seriousness of the injury, and the burden of avoiding the risk’ ” (Basso v. Miller, 40 N.Y.2d at 241, 386 N.Y.S.2d 564, 352 N.E.2d 868, quoting Smith v. Arbaugh''s Rest., Inc., 469 F.2d 97, 100 [D.C. Cir.1972], cert. denied 412 U.S. 939, 93 S.Ct. 2774, 37 L.Ed.2d 399 [1973]; accord Peralta v. Henriquez, 100 N.Y.2d at 144, 760 N.Y.S.2d 741, 790 N.E.2d 1170).', 'mbe_2362', 0, '30'),
('mbe_452', 'mbe', '452', '269', 'MBE-1978-83-part6', '', '52', '', 'Zeller contracted in writing to deliver to Baker 100 bushels of wheat on August 1 at $3.50 a bushel. Because his suppliers had not delivered enough wheat to him by that time, Zeller on August 1 had only 95 bushels of wheat with which to fulfill his contract with Baker. If Zeller tenders 95 bushels of wheat to Baker on August 1, and Baker refused to accept or pay for any of the wheat, which of the following best states the legal relationship between Zeller and Baker?', 'Zeller has a cause of action against Baker, because Zeller has substantially performed his contract.', 'Zeller is excused from performing his contract because of impossibility of performance.', 'Baker has a cause of action against Zeller for Zeller''s failure to deliver 100 bushels of wheat.', 'Baker is obligated to give Zeller a reasonable time to attempt to obtain the other five bushels of wheat.', 'C', 'Accordingly, breach of contract remedies are available to a buyer when the seller fails to make any delivery. S.W. Bell, 811 S.W.2d at 576. In contrast, breach of warranty remedies are available to a buyer who has received and accepted goods, but discovers they are defective in some manner.  Id. In other words, when a party fails to deliver the goods as promised, a breach of contract occurs. See Chilton Ins. Co. v. Pate & Pate Enter., Inc., 930 S.W.2d 877, 890 (Tex.App.-San Antonio 1996, writ denied). Conversely, when a seller delivers nonconforming goods, it is a breach of warranty. Id. Under the Uniform Commercial Code (“UCC”), breach of contract damages are available for failure to perform, but not for delivery of nonconforming goods. Id. We believe that the Chilton court makes a definitive distinction between failure to conform and failure to deliver. See id.', 'mbe_2363', 0, '52'),
('mbe_471', 'mbe', '471', '284', 'MBE-1985-part7', '', '19', '', 'Pratt sued Danvers for injuries suffered by Pratt when their automobiles collided. At trial, Pratt offers into evidence a properly authenticated letter from Danvers that says, "Your claim seems too high, but, because I might have been a little negligent, I''m prepared to offer you half of what you ask" The letter is', 'admissible as an admission by a party-opponent', 'admissible as a statement against pecuniary interest', 'inadmissible, because Danver''s statement is lay opinion on a legal issue', 'inadmissible, because Danver''s statement was made in an effort to settle the claim', 'D', 'The Federal Rules of Evidence govern the admissibility of evidence generally. See Fed.R.Evid. 401–04. Irrelevant evidence is not admissible. Fed.R.Evid. 402. Similarly, unfairly 3 prejudicial or misleading evidence is not admissible. Fed.R.Evid. 403.  As a general matter, hearsay statements are not admissible; however, there are several exceptions to that rule which require the Court to look at each individual statement on a case-by-case basis. See Fed.R.Evid. 801–07. Rule 804(b)(3) excepts from the hearsay rule statements against interest made by a declarant who is unavailable to testify at trial, including statements that tend to expose the declarant to criminal liability. Fed.R.Evid. 804(b)(3). Statements that are not inculpatory are not admissible pursuant to this rule even if they are part of a generally inculpatory statement or narrative. United States v. Ricardo, 472 F.3d 277, 287 (5th Cir.2006) (citing Williamson, 512 U.S. at 600–01). However, these rules cannot be applied except in the context of specific evidence.', 'mbe_2364', 0, '19')
ON CONFLICT (idx) DO NOTHING;
